(497,0,NULL,38578,NULL,NULL,'2022-06-28 23:02:09','2025-12-19 12:46:01',NULL,2,0,'chapter',NULL,NULL,'','Eine Transkription in erster Ebene der Einleitungskapitel<bl id=\"5fd2058a21a04fe7e72d72dd4878de16\"><vz id=\"d4625aa3c9f447faeaf26a152730b2fa\" />Transkription mit einer nicht eingerückten Verzeile und Seitenzahlanker<nl /><anchor id=\"ebf96a7f101e48e6e819d4aa6a7d7bd1\" value=\"46\" format=\"\" /><nl /><vz id=\"caf0a717bb284c53ee1ae742fcd9c253\" />und einer eingerückten Verszeile mit Fußnote<app1 id=\"6b3e37fcfe5b460eb9710cf940136dba\" /><nl /> </bl>Danach geht der Text weiter.',NULL,0,NULL,NULL,NULL,NULL,'',NULL,'','',NULL,NULL,0,NULL,'',NULL,NULL,NULL,0,NULL,NULL,0,0,0,NULL,2,230),
