(5820,0,NULL,NULL,NULL,NULL,'2025-11-11 10:26:34','2026-03-29 09:50:40',6,2,NULL,'transcriptions',NULL,NULL,NULL,'<bl id=\"a430380377ad4010f1d21232346366d9\">An die Freude</bl><bl id=\"ccd4552eeb3d4b7fcdb05969274619eb\">Freude, schöner Götterfunken<nl /><vz id=\"bf98704973744719d9749449d60c37bd\" />Tochter aus Elisium,<nl /><vz id=\"f813c23be04e4311a88672678ba70568\" />Wir betreten feuertrunken<nl /><vz id=\"31981ddc174c4a74f9afe6a0d874c32e\" />Himmlische, dein Heiligthum.<nl /><vz id=\"babb2a627e7c40eb985ad53b0f0b2d11\" />Deine Zauber binden wieder,<nl /><vz id=\"9153974c5ac949f3e3e19838722494dc\" />was der Mode Schwerd getheilt;<nl /><vz id=\"99583caf994d4ae6a3a9532645ff7826\" />Bettler werden Fürstenbrüder,<nl /><vz id=\"6dffb49c51104f339c43b500724c9c51\" />wo dein sanfter Flügel weilt.<nl /> </bl>','',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','',NULL,NULL,0,'','Conrady',NULL,NULL,NULL,NULL,19,2564),
