(6263,0,NULL,NULL,NULL,NULL,'2025-11-11 14:45:53','2026-03-29 09:50:40',6,2,NULL,'transcriptions',NULL,NULL,NULL,'<bl id=\"fd97fdb25d544b78a01c5c3c010406aa\">Seid umschlungen Millionen! <z id=\"0008be491b6e46298773ec43bf864b89\" /><nl />Diesen Kuß der ganzen Welt!<z id=\"304cbca79f4444fa8e10ddd07b40def6\" /><nl />Brüder – überm Sternenzelt<z id=\"6753962393864231cfe3c25cc8f9c51b\" /><nl />muß ein lieber Vater wohnen.<nl /> </bl>','',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','',NULL,NULL,0,'','',NULL,NULL,NULL,NULL,19,2781),
