(10515,0,NULL,NULL,NULL,NULL,'2026-05-08 15:17:41','2026-05-08 15:17:41',2,2,NULL,'search',NULL,NULL,'Transkription','Grímr unni henni mikit, ok lætr hann þat eptir henni. \nHún var hverri konu vænni ok betr at sér um alla hluti,\nþeira er í Noregi váru. \nÞeira för var búin virðuliga.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,18),
